// Fetch multiple RSS feeds for global market news
const feeds = [
  { name: 'Reuters Business', url: 'https://feeds.reuters.com/reuters/businessNews' },
  { name: 'Yahoo Finance', url: 'https://finance.yahoo.com/news/rssindex' },
  { name: 'CNBC Top News', url: 'https://search.cnbc.com/rs/search/combinedcms/view.xml?partnerId=wrss01&id=100003114' },
  { name: 'MarketWatch', url: 'https://feeds.marketwatch.com/marketwatch/topstories/' },
  { name: 'Investing.com', url: 'https://www.investing.com/rss/news.rss' }
];

return feeds.map(f => ({ json: f }));

// Parse RSS XML and extract article titles + descriptions
const items = $input.all();
const articles = [];

for (const item of items) {
  const xml = item.json.data || '';
  const feedName = item.json.name || 'Unknown';

  // Extract <item> elements from RSS
  const itemMatches = xml.match(/<item[^>]*>([\s\S]*?)<\/item>/gi) || [];

  for (const rawItem of itemMatches.slice(0, 8)) { // Max 8 per feed
    const titleMatch = rawItem.match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/);
    const descMatch = rawItem.match(/<description>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/description>/);
    const pubDateMatch = rawItem.match(/<pubDate>([\s\S]*?)<\/pubDate>/);

    const title = titleMatch ? titleMatch[1].trim().replace(/<[^>]+>/g, '') : '';
    const desc = descMatch ? descMatch[1].trim().replace(/<[^>]+>/g, '').substring(0, 300) : '';

    if (title && title.length > 10) {
      articles.push(`[${feedName}] ${title}. ${desc}`);
    }
  }
}

// Deduplicate and limit
const unique = [...new Set(articles)].slice(0, 40);
const newsText = unique.join('\n---\n');

console.log(`Collected ${unique.length} articles for AI analysis`);

return [{ json: { news_text: newsText, article_count: unique.length, fetched_at: new Date().toISOString() } }];

// Parse OpenAI response and build final market_brief.json
const response = $input.first();
const rawContent = response.json.message?.content || response.json.choices?.[0]?.message?.content || '';

let brief = {};
try {
  // Clean potential markdown code blocks
  let cleaned = rawContent.trim();
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```[\w]*\n?/, '').replace(/\n?```$/, '');
  }
  brief = JSON.parse(cleaned);
} catch (e) {
  console.error('Failed to parse OpenAI JSON:', e.message);
  brief = {
    error: 'Failed to parse AI response',
    raw: rawContent.substring(0, 500),
    generated_at: new Date().toISOString(),
    overall_sentiment: 'NEUTRAL',
    sentiment_score: 0,
    executive_summary: 'Анализът временно не е наличен. Моля, опитайте отново.',
    macro: { sentiment: 'NEUTRAL', emoji: '🌍', title: 'Макро & Геополитика', summary: 'Няма данни', key_points: [] },
    equities: { sentiment: 'NEUTRAL', emoji: '📈', title: 'Акции & Индекси', summary: 'Няма данни', key_points: [], hot_sectors: [] },
    gold: { sentiment: 'NEUTRAL', emoji: '🥇', title: 'Злато & Суровини', summary: 'Няма данни', key_points: [] },
    crypto: { sentiment: 'NEUTRAL', emoji: '₿', title: 'Криптовалути', summary: 'Няма данни', key_points: [] },
    risk_factors: [],
    opportunities: [],
    watchlist_impact: 'Няма данни'
  };
}

brief.generated_at = new Date().toISOString();
brief.source = 'OpenAI GPT-4o via RSS Feeds';

return [{ json: { market_brief: brief, brief_json: JSON.stringify(brief) } }];
